argv:
$ErrorActionPreference='Stop'
function Read-Local($p){return Invoke-RestMethod -Uri ('http://127.0.0.1:17448'+$p) -Method Get -TimeoutSec 15}
Write-Output '=== READONLY CONTROL STATUS ==='
try {
 $s=Read-Local '/api/supervisor-watchdog?detect=0'
 Write-Output ('SUPERVISOR_RUNNING='+$s.runtime.processRunning)
 Write-Output ('SUPERVISOR_MODE='+$s.config.mode)
 Write-Output ('SUPERVISOR_ALLOW_SEND='+$s.config.allowAutonomousSend)
 Write-Output ('SUPERVISOR_AUTO_CONTINUE='+$s.config.autoContinueEnabled)
 Write-Output ('SUPERVISOR_ENFORCE_HIGH='+$s.config.enforceHighMode)
 Write-Output ('SUPERVISOR_HIGH_STRATEGY='+$s.config.highModeStrategy)
 Write-Output ('SUPERVISOR_PARALLEL='+$s.config.maxParallelAgents)
 Write-Output ('SUPERVISOR_CLOSE_ON_BACKOFF='+$s.config.closeChatDuringProviderBackoff)
 Write-Output ('SUPERVISOR_OPEN_MISSING='+$s.config.openExistingChatIfMissing)
}catch{Write-Output ('SUPERVISOR_GET_FAILED='+$_.Exception.Message.Substring(0,[Math]::Min(90,$_.Exception.Message.Length)))}
try{
 $r=Read-Local '/api/projects/control-plane/cutover-r42/status'
 Write-Output ('R42_HOLD='+$r.cutoverState.holdActive)
 Write-Output ('R42_STATUS='+$r.cutoverState.status)
 Write-Output ('R42_VALIDATION_OK='+$r.autonomy.validation.ok)
}catch{Write-Output ('R42_GET_FAILED='+$_.Exception.Message.Substring(0,[Math]::Min(90,$_.Exception.Message.Length)))}
try{
 $d=Read-Local '/api/supervisor-watchdog/agent-assignments/dry-run'
 $rows=@($d.rows)
 Write-Output ('DRYRUN_ROWS='+$rows.Count)
 $n=0
 foreach($row in $rows){
  $n++
  $sn=@($row.snapshots)
  $high=@($sn|Where-Object {$_.highMode -eq $true}).Count
  $generating=@($sn|Where-Object {$_.generating -eq $true}).Count
  $bad=@($sn|Where-Object {$_.providerLoadError -eq $true}).Count
  Write-Output ('ROW_'+$n+' preflight='+$row.preflightReason+' high_snapshots='+$high+' generating='+$generating+' provider_errors='+$bad+' openTabs='+$row.openTabs+' schedulerSelected='+$row.schedulerSelected)
 }
}catch{Write-Output ('DRYRUN_GET_FAILED='+$_.Exception.Message.Substring(0,[Math]::Min(90,$_.Exception.Message.Length)))}
Write-Output '=== END ==='
